@torch.no_grad()
def _make_emb_viz(zs, epoch=-1, title='Embeddings', do_umap=True, file_idx=None, deltas=None):
    "visualize embeddings, projected"
    if zs is None:  return {} # 'pca':pca_fig, 'umap':umap_fig} if umap_fig is not None else {'pca':pca_fig}
    umap_fig, pca_fig = None, None
    if do_umap:
        coords = umap_project(zs)
        umap_fig = plot_embeddings_3d(coords, title=title+f' (UMAP), epoch {epoch}', file_idx=file_idx, deltas=deltas)
    if torch.cuda.is_available(): torch.cuda.synchronize() # cleanup before PCA or else you get CUDA errors
    gc.collect()
    coords = pca_project(zs)
    pca_fig = plot_embeddings_3d(coords, title=title+f' (PCA), epoch {epoch}', file_idx=file_idx, deltas=deltas)
    if wandb.run is not None: 
        if do_umap and umap_fig is not None:
            wandb.log({f"{title} UMAP": wandb.Html(umap_fig.to_html()), f"{title} PCA": wandb.Html(pca_fig.to_html())})
        if pca_fig is not None:
            wandb.log({f"{title} PCA": wandb.Html(pca_fig.to_html())})
    if torch.cuda.is_available(): torch.cuda.synchronize() # cleanup again
    gc.collect()
    return {'pca':pca_fig, 'umap':umap_fig} if umap_fig is not None else {'pca':pca_fig}

# %% ../nbs/05_viz.ipynb #b618d453
def _subsample(data, indices, deltas, max_points, debug=False):
    "Subsample data and indices together, in pairs"
    perm1 = torch.randperm(len(data)//2)[:max_points//2]
    perm2 = perm1 + len(data)//2
    perm = torch.cat([perm1,perm2])
    return data[perm], indices[perm], deltas[perm]

# %% ../nbs/05_viz.ipynb #eceafaa0-dad6-43cd-ab67-7abbe8d13ab8
def _gather_level(enc_outs,        # list of encoder outputs
                  lev,             # level of hierarchy: 0=coarsest, -1=finest
                  batch=None):     #  info from dataset, e.g. file_idx, deltas
    "Consolidates all embeddings at a given level for visualization"
    eo0     = enc_outs[0]                     # used for info that's the same for all enc_outs
    edim    = eo0.patches[lev].dim            # embedding dimensions at this level
    N       = eo0.patches[lev].num_patches    # num patch tokens at this level
    n_eo    = len(enc_outs)                   # num encoder outs (e.g. 2)
    device  = eo0.patches[lev].emb.device     # assume same device for all eo's
    emb, non_empty, joint_non_empty = [], [], None
    for eo in enc_outs: 
        emb.append( eo.patches[lev].emb )  
        this_ne = eo.patches[lev].non_empty.bool() 
        non_empty.append( this_ne )
        joint_non_empty = this_ne if joint_non_empty is None else joint_non_empty & this_ne
    emb, non_empty = torch.cat(emb, dim=0), torch.cat(non_empty, dim=0)      # cat along batch dim
    non_empty, joint_non_empty = non_empty.flatten(), joint_non_empty.repeat(n_eo,1).flatten()

    if batch is None: return emb.reshape(-1, edim), non_empty, joint_non_empty,  None, None  # (BT*N, edim), (BT*N,), (BT*N,), where BT = B*n_eo    
    file_idx = batch['file_idx'].repeat(n_eo).repeat_interleave(N).to(device)
    deltas = batch['deltas'][:, 0, :].repeat(n_eo, 1).repeat_interleave(N, dim=0).to(device)
    return emb.reshape(-1, edim), non_empty,  joint_non_empty, file_idx, deltas     # (BT*N, edim), (BT*N,), (BT*N,), (BT*N,), (BT*N,2)

# %% ../nbs/05_viz.ipynb #a64048f1
@torch.no_grad()
def make_emb_viz(enc_outs, epoch=-1, encoder=None, batch=None, title='Embeddings', max_points=5000, do_umap=False, debug=False):
    "this is the main viz routine, showing different groups of embeddings"
    if not isinstance(enc_outs, (list, tuple)): enc_outs = [enc_outs]
    device = enc_outs[0].patches[0].emb.device
    if encoder is not None: encoder.to('cpu')
    torch.cuda.empty_cache()
    figs = [] 
    for lev in range(enc_outs[0].patches.num_levels):
        emb, non_empty, joint_non_empty, file_idx, deltas = _gather_level(enc_outs, lev, batch=batch)
        lev_figs = {}
        for mask, label in [(joint_non_empty, 'joint_non_empty'), (~non_empty, 'empty')]:
            if not mask.any(): continue
            rnd_emb, rnd_fi, rnd_d = _subsample(emb[mask], file_idx[mask], deltas[mask], max_points)
            lev_figs[label] = _make_emb_viz(rnd_emb.cpu(), epoch=epoch, title=f'{label} Level {lev} (dim={emb.shape[-1]}), {title}', file_idx=rnd_fi, deltas=rnd_d, do_umap=do_umap)
        figs.append(lev_figs)
    if encoder is not None: encoder.to(device)
    return figs

# %% ../nbs/05_viz.ipynb #5f2723b2-287c-427a-822b-f2f9e715169b
def _cell_title(figs, lev, label):
    if label not in figs[lev] or 'pca' not in figs[lev][label]: return ""
    n_pts = sum(len(t.x) for t in figs[lev][label]['pca'].data)
    return f"Level {lev} {label} (N={n_pts})"
    
def show_fig_table(figs):
    "Display all PCA figs in a grid: rows=levels, cols=non_empty|empty"
    from plotly.subplots import make_subplots
    n_levels = len(figs)
    col_labels = ['joint_non_empty', 'empty']
    specs = [[{'type': 'scene'} for _ in col_labels] for _ in reversed(range(n_levels))]
    subplot_titles = [_cell_title(figs, lev, lab) for lev in reversed(range(n_levels)) for lab in col_labels]
    big_fig = make_subplots(rows=n_levels, cols=2, specs=specs, subplot_titles=subplot_titles, 
                            vertical_spacing=0.03, horizontal_spacing=0.02)
    for row, lev_dict in enumerate(reversed(figs)):
        lev = n_levels - 1 - row
        for col_idx, label in enumerate(col_labels):
            if label not in lev_dict or 'pca' not in lev_dict[label]: continue
            for trace in lev_dict[label]['pca'].data:
                big_fig.add_trace(trace, row=row+1, col=col_idx+1)

    big_fig.update_layout(height=300*n_levels, width=800, title_text="Embeddings by Level (PCA)",
                      margin=dict(l=20, r=20, t=40, b=20), showlegend=False)

    big_fig.show()

# %% ../nbs/05_viz.ipynb #f450ea65-c24c-4675-894d-792ee4a9b986
def expand_patch_mask(mae_mask, grid_h, grid_w, patch_size):
    """Expand patch-level mask (N,) to pixel-level mask (H, W)"""
    return mae_mask.bool().reshape(grid_h, grid_w).repeat_interleave(patch_size, 0).repeat_interleave(patch_size, 1)

# %% ../nbs/05_viz.ipynb #6be20056-1385-46cc-972f-ab1207bce9a6
def do_recon_eval(recon, real, mae_mask=None, patch_size=16, eps=1e-8, return_maps=False): 
    "Evaluate recon accuracy, optionally only on masked patches"
    # Full spatial maps (B, C, H, W) — before any masking
    TPmap = (recon * real).bool()
    FPmap = (recon * (1 - real)).bool()
    FNmap = ((1 - recon) * real).bool()
    TNmap = ((1 - recon) * (1 - real)).bool()

    # Aggregate only over masked patches if applicable
    if mae_mask is not None: 
        B, C, H, W = real.shape
        grid_h, grid_w = H // patch_size, W // patch_size
        masked = ~expand_patch_mask(mae_mask, grid_h, grid_w, patch_size)
        TP, FP, FN, TN = (m[:, :, masked].sum() for m in (TPmap, FPmap, FNmap, TNmap))
    else:
        TP, FP, FN, TN = (m.sum() for m in (TPmap, FPmap, FNmap, TNmap))

    precision = TP / (TP + FP + eps) 
    recall = TP / (TP + FN + eps) 
    specificity = TN / (TN + FP + eps) 
    f1 = 2 * precision * recall / (precision + recall + eps) 
    evals = {'precision': precision, 'recall': recall, 'specificity': specificity, 'f1': f1}
    if wandb.run is not None: wandb.log(evals) 
    if return_maps: evals = evals | {'TPmap': TPmap, 'TNmap': TNmap, 'FPmap': FPmap, 'FNmap': FNmap}
    return evals 

# %% ../nbs/05_viz.ipynb #1aaee236-717b-408c-8252-2e0048f63211
def patches_to_img(recon_patches, img_real, patch_size=16, mae_mask=None):
    "Convert image patches to full image. Copy over real patches where appropriate."
    B, C, H, W = img_real.shape
    grid_h, grid_w = H//patch_size, W//patch_size
    n_patches = grid_h * grid_w
    if recon_patches.shape[1] > n_patches: recon_patches = recon_patches[:, -n_patches:]  # strip cls if present
    img_recon = recon_patches.reshape(B, grid_h, grid_w, patch_size, patch_size).permute(0, 1, 3, 2, 4)
    img_recon = img_recon.reshape(B, H, W).unsqueeze(1)
    img_recon = torch.sigmoid(img_recon)
    img_recon = (img_recon > 0.5).float()
    if mae_mask is not None:
        vis_2d = expand_patch_mask(mae_mask, grid_h, grid_w, patch_size)
        img_recon[:, :, vis_2d] = img_real[:, :, vis_2d]
    return img_recon 

# %% ../nbs/05_viz.ipynb #86455273-d2fa-4a97-a6a7-0a71a0a7798f
@torch.no_grad()
def viz_mae_recon(recon, img_real, enc_out=None, epoch=-1, patch_size=16, debug=False, return_maps=False):
    """Show how our LightweightMAEDecoder is doing (during encoder training)"""
    mae_mask = None
    if enc_out is not None:
        mae_mask = enc_out.mae_mask
        if mae_mask.ndim == 2: mae_mask = mae_mask[0]   # Swin: (B,N) → take first sample
        elif mae_mask.shape[0] % 2 != 0: mae_mask = mae_mask[1:]  # ViT: strip CLS from (N,)
    recon, img_real = recon.cpu(), img_real.cpu()
    if mae_mask is not None: mae_mask = mae_mask.cpu()
    if debug: print(f"mae_mask: shape={mae_mask.shape}, pct_visible={mae_mask.float().mean():.3f}")

    img_recon_noreplace = None
    if recon.shape != img_real.shape:
        img_recon = patches_to_img(recon, img_real, patch_size=patch_size, mae_mask=mae_mask)
        img_recon_noreplace = patches_to_img(recon, img_real, patch_size=patch_size, mae_mask=None)
    else:
        img_recon = (recon > 0.25).float()
    evals = do_recon_eval(img_recon, img_real, mae_mask=mae_mask, patch_size=patch_size, return_maps=return_maps)
    grid_recon = make_grid(img_recon[:64], nrow=8, normalize=True)
    grid_real  = make_grid(img_real[:64], nrow=8, normalize=True)
    if return_maps:  # RGB image: White=TP, Black=TN, Red=FP, Yellow=FN 
        r  = (evals['TPmap'] | evals['FPmap'] | evals['FNmap']).float()
        g  = (evals['TPmap'] | evals['FNmap']).float()
        b  = (evals['TPmap']).float()
        img_map = torch.cat((r, g, b), dim=1)
        grid_map = make_grid(img_map[:64], nrow=8, normalize=True)
    if wandb.run is not None:
        wandb_dict = {'real': wandb.Image(grid_real, caption=f"Epoch {epoch}"),
                      'recon': wandb.Image(grid_recon, caption=f"Epoch {epoch}"), 'epoch': epoch}
        if return_maps: wandb_dict = wandb_dict | {'map': wandb.Image(grid_map, caption=f"Epoch {epoch}, Red=FP, Yellow=FN") }
        if img_recon_noreplace is not None:
            grid_raw = make_grid(img_recon_noreplace[:64], nrow=8, normalize=True)
            wandb_dict = wandb_dict | {'raw': wandb.Image(grid_raw, caption=f"Epoch {epoch}")}
        wandb.log(wandb_dict)
    if return_maps: return grid_recon, grid_real, grid_map, evals
    else: return grid_recon, grid_real, evals
